from typing import Callable, List, TypeVar
A = TypeVar('A')
from dataclasses import dataclass
from typing import Generic, Union

@dataclass(frozen=True)
class Leaf(Generic[A]):
    value: A

@dataclass(frozen=True)
class Node(Generic[A]):
    left: 'BTree'
    right: 'BTree'

BTree = Union[Leaf, Node]

def merkle_damgard(f, iv, msg):
    acc = iv
    for b in msg:
        acc = f(acc, b)
    return acc

def tree_hash(g, h, t):
    if isinstance(t, Leaf):
        return g(t.value)
    return h(tree_hash(g, h, t.left), tree_hash(g, h, t.right))

def left_comb(a, bs):
    t = Leaf(a)
    for b in bs:
        t = Node(t, Leaf(b))
    return t

def nat_pair(a, b):
    return b*b+a if a < b else a*a+a+b

h, a, bs = nat_pair, 5, [1, 2, 3, 4]
lhs = tree_hash(lambda x: x, h, left_comb(a, bs))
rhs = merkle_damgard(h, a, bs)
print('bridge holds:', lhs == rhs, '(', lhs, '==', rhs, ')')

