function TAGGED_TREE_HASH(g, h, t):
    if t is Leaf(x):
        return 2 * g(x)               # even tag class
    else:                             # t is Node(l, r)
        L <- TAGGED_TREE_HASH(g, h, l)
        R <- TAGGED_TREE_HASH(g, h, r)
        return 2 * h(L, R) + 1        # odd tag class

